; DVMM.S - VMM TEST PAGE RENDERER AND TEST ALGORITHM (WP8)
;
; ALLOCATES ONE 4KB PAGE (256 PARAGRAPHS) VIA DOS_ALLOC_MEM ($48), WRITES AND
; READS BACK THREE DETERMINISTIC PATTERNS ACROSS ALL 16 OF ITS 256-BYTE
; BLOCKS, AND FREES ON EVERY POST-ALLOCATION PATH VIA DOS_FREE_MEM ($49).
; DEGRADES SAFELY (NO ALLOCATION ATTEMPTED AT ALL) WHEN DOS_GET_SYSTEM_INFO
; ($5C) REPORTS VMM INACTIVE. NEVER TOUCHES REU/MCT REGISTERS DIRECTLY --
; EXCLUSIVELY THE PUBLIC $48/$49/$59/$5A/$5C API, LIKE EVERY OTHER DASH PAGE.
;
; ALL 16 TRANSFER BLOCKS ARE 256-BYTE ALIGNED ($0000, $0100, ..., $0F00), SO
; VMMOFFLO ($6A) IS ALWAYS 0 AND VMMOFFHI ($6B) IS EXACTLY THE BLOCK INDEX
; (0-15) -- THE HIGHEST OFFSET EVER TOUCHED IS $0FFF, NEVER $1000.

; DVMMRENDER - TOP-LEVEL VMM-PAGE REDRAW ENTRY POINT.
; INPUT: NONE. OUTPUT: NONE. CLOBBERS: A, X, Y.
DVMMRENDER:
    JSR CLEARSCREEN
    JSR DRAWFRAME

    LDA #COL_CONTENT
    LDY #ROW_VMM_TITLE
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMMTITLESTR
    LDY #>VMMTITLESTR
    JSR SCREENPUTSTRING

    JSR DVMMREFRESHCAP
    JSR DVMMRENDERSTATUS
    JSR DVMMRENDERDETAIL
    RTS

; DVMMREFRESHCAP - REFRESHES VMMPAGESTATE FROM A LIVE DOS_GET_SYSTEM_INFO
; CAPABILITY CHECK, UNLESS AN ALLOCATION IS CURRENTLY OWNED OR CLEANUP HAS
; ALREADY FAILED -- NEITHER CASE MAY EVER BE OVERWRITTEN BY A FRESH READ, OR
; A SECOND ALLOCATION COULD BE ATTEMPTED ON TOP OF ONE STILL OUTSTANDING.
; REUSES DSYS.S'S QUERYSYSTEMINFO/SYSINFOBUF -- THE PLAN'S APPROVED
; CAPABILITY-REFRESH REUSE.
; CLOBBERS: A, X, Y.
DVMMREFRESHCAP:
    LDA VMMOWNED
    BNE @DONE
    LDA VMMPAGESTATE
    CMP #VMMSTATE_CLEANUPFAIL
    BEQ @DONE

    JSR QUERYSYSTEMINFO
    BCS @UNAVAIL
    LDA SYSINFOBUF+SYS_OFF_STRUCTVERSION
    CMP #SYS_STRUCT_VERSION
    BNE @UNAVAIL
    LDA SYSINFOBUF+SYS_OFF_STRUCTSIZE
    CMP #SYS_STRUCT_SIZE
    BNE @UNAVAIL
    LDA SYSINFOBUF+SYS_OFF_VMMFLAGS
    AND #SYS_VMMFLAG_ACTIVE
    BEQ @UNAVAIL

    ; VMM ACTIVE. PROMOTE UNAVAILABLE -> READY. LEAVE PASSED/FAILED/RUNNING
    ; ALONE SO A PRIOR RESULT STAYS ON SCREEN UNTIL THE USER RETESTS.
    LDA VMMPAGESTATE
    BNE @DONE
    LDA #VMMSTATE_READY
    STA VMMPAGESTATE
    RTS
@UNAVAIL:
    LDA #VMMSTATE_UNAVAIL
    STA VMMPAGESTATE
@DONE:
    RTS

; DVMMRENDERSTATUS - ROW 6: "STATUS: " + THE CURRENT STATE WORD.
; CLOBBERS: A, X, Y.
DVMMRENDERSTATUS:
    LDA #COL_CONTENT
    LDY #ROW_VMM_STATUS
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMMLABEL1
    LDY #>VMMLABEL1
    JSR SCREENPUTSTRING

    LDA VMMPAGESTATE
    CMP #VMMSTATE_UNAVAIL
    BEQ @UNAVAIL
    CMP #VMMSTATE_READY
    BEQ @READY
    CMP #VMMSTATE_RUNNING
    BEQ @RUNNING
    CMP #VMMSTATE_PASSED
    BEQ @PASSED
    CMP #VMMSTATE_FAILED
    BEQ @FAILED
    LDX #<VMML_CLEANUPFAIL
    LDY #>VMML_CLEANUPFAIL
    JMP @PRINT
@UNAVAIL:
    LDX #<VMML_UNAVAILSHORT
    LDY #>VMML_UNAVAILSHORT
    JMP @PRINT
@READY:
    LDX #<VMML_READY
    LDY #>VMML_READY
    JMP @PRINT
@RUNNING:
    LDX #<VMML_RUNNING
    LDY #>VMML_RUNNING
    JMP @PRINT
@PASSED:
    LDX #<VMML_PASSED
    LDY #>VMML_PASSED
    JMP @PRINT
@FAILED:
    LDX #<VMML_FAILED
    LDY #>VMML_FAILED
@PRINT:
    LDA #SCREEN_COLS
    JSR SCREENPUTSTRING
    RTS

; DVMMRENDERDETAIL - ROWS 8-14: ALLOCATION IDENTITY, PATTERN PROGRESS,
; FAILURE STAGE/OFFSET/BYTES (WHEN APPLICABLE), AND THE BOTTOM INSTRUCTION
; LINE, ALL GATED ON VMMPAGESTATE. NO ROW IS EVER MISSING ITS GUARD: EVERY
; SECTION BELOW EITHER PRINTS OR FALLS THROUGH, NEVER BOTH.
; CLOBBERS: A, X, Y.
DVMMRENDERDETAIL:
    LDA VMMPAGESTATE
    CMP #VMMSTATE_RUNNING
    BCS @HASRUN           ; HAVE A CAPTURED IDENTITY/PATTERN TO SHOW
    JMP @INSTRUCTION
@HASRUN:
    LDA #COL_CONTENT
    LDY #ROW_VMM_ALLOC
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMML_ALLOC
    LDY #>VMML_ALLOC
    JSR SCREENPUTSTRING

    LDA #SCREEN_COLS
    LDX #<VMML_SEGBANK
    LDY #>VMML_SEGBANK
    JSR SCREENPUTSTRING
    LDA VMMSEGHI
    JSR FORMATHEX8
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #SCREEN_COLS
    LDX #<VMML_BANK
    LDY #>VMML_BANK
    JSR SCREENPUTSTRING
    LDA VMMBANKID
    JSR FORMATHEX8
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #COL_CONTENT
    LDY #ROW_VMM_PATTERN
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMML_PATTERN
    LDY #>VMML_PATTERN
    JSR SCREENPUTSTRING
    LDX VMMPATTERNIDX
    INX                          ; DISPLAY 1-BASED (1/3, 2/3, 3/3)
    LDY #0
    JSR PRINTDEC16
    LDA #SCREEN_COLS
    LDX #<VMML_OF3
    LDY #>VMML_OF3
    JSR SCREENPUTSTRING

    LDA VMMPAGESTATE
    CMP #VMMSTATE_FAILED
    BEQ @SHOWFAIL
    CMP #VMMSTATE_CLEANUPFAIL
    BEQ @SHOWFAIL
    JMP @INSTRUCTION

; @SHOWFAIL - ROW 10: "STAGE: " + FAILURE STAGE NAME. ROWS 11-12 (THE
; OFFSET/EXPECTED/ACTUAL BYTES) ONLY APPLY TO A COMPARE-STAGE FAILURE.
@SHOWFAIL:
    LDA #COL_CONTENT
    LDY #ROW_VMM_STAGE
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMML_STAGE
    LDY #>VMML_STAGE
    JSR SCREENPUTSTRING

    LDA VMMFAILSTAGE
    CMP #VMMFAIL_ALLOC
    BEQ @STGALLOC
    CMP #VMMFAIL_WRITE
    BEQ @STGWRITE
    CMP #VMMFAIL_READ
    BEQ @STGREAD
    CMP #VMMFAIL_COMPARE
    BEQ @STGCOMPARE
    CMP #VMMFAIL_FREE
    BEQ @STGFREE
    LDX #<VMMST_INTERNAL
    LDY #>VMMST_INTERNAL
    JMP @STGPRINT
@STGALLOC:
    LDX #<VMMST_ALLOC
    LDY #>VMMST_ALLOC
    JMP @STGPRINT
@STGWRITE:
    LDX #<VMMST_WRITE
    LDY #>VMMST_WRITE
    JMP @STGPRINT
@STGREAD:
    LDX #<VMMST_READ
    LDY #>VMMST_READ
    JMP @STGPRINT
@STGCOMPARE:
    LDX #<VMMST_COMPARE
    LDY #>VMMST_COMPARE
    JMP @STGPRINT
@STGFREE:
    LDX #<VMMST_FREE
    LDY #>VMMST_FREE
@STGPRINT:
    LDA #SCREEN_COLS
    JSR SCREENPUTSTRING

    LDA VMMFAILSTAGE
    CMP #VMMFAIL_COMPARE          ; ONLY A COMPARE FAILURE HAS A MEANINGFUL
    BEQ @SHOWOFFSET         ; OFFSET/EXPECTED/ACTUAL TO SHOW
    JMP @INSTRUCTION
@SHOWOFFSET:
    LDA #COL_CONTENT
    LDY #ROW_VMM_OFFSET
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMML_OFFSET
    LDY #>VMML_OFFSET
    JSR SCREENPUTSTRING
    LDX VMMFAILOFFLO
    LDY VMMFAILOFFHI
    JSR FORMATHEX16
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #COL_CONTENT
    LDY #ROW_VMM_EXPECT
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<VMML_EXPECT
    LDY #>VMML_EXPECT
    JSR SCREENPUTSTRING
    LDA VMMFAILEXPECT
    JSR FORMATHEX8
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #SCREEN_COLS
    LDX #<VMML_ACTUAL
    LDY #>VMML_ACTUAL
    JSR SCREENPUTSTRING
    LDA VMMFAILACTUAL
    JSR FORMATHEX8
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING
    ; FALLS THROUGH TO @INSTRUCTION BELOW.

; @INSTRUCTION - ROW 14: BOTTOM INSTRUCTION/EXPLANATION LINE.
@INSTRUCTION:
    LDA #COL_CONTENT
    LDY #ROW_VMM_INSTR
    JSR SCREENSETCURSOR

    LDA VMMPAGESTATE
    CMP #VMMSTATE_UNAVAIL
    BEQ @INSTRUNAVAIL
    CMP #VMMSTATE_CLEANUPFAIL
    BEQ @INSTRRESTART
    LDX #<VMML_PRESST
    LDY #>VMML_PRESST
    JMP @INSTRPRINT
@INSTRUNAVAIL:
    LDX #<VMML_UNAVAIL
    LDY #>VMML_UNAVAIL
    JMP @INSTRPRINT
@INSTRRESTART:
    LDX #<VMML_RESTART
    LDY #>VMML_RESTART
@INSTRPRINT:
    LDA #SCREEN_COLS
    JSR SCREENPUTSTRING
    RTS

; --- TEST ALGORITHM (WIRED TO 'T'/'T' ON THIS PAGE ONLY, SEE DMAIN.S) ---

; DVMMRUNTEST - RUNS THE FULL ALLOCATE/WRITE/READ/COMPARE/FREE CYCLE ACROSS
; ALL 3 PATTERNS AND ALL 16 BLOCKS OF ONE 4KB PAGE.
;
; INPUT: NONE. OUTPUT: VMMPAGESTATE/VMMFAILSTAGE/VMMFAILOFF*/VMMFAIL* UPDATED.
; REJECTS SILENTLY (NO STATE CHANGE) IF AN ALLOCATION IS ALREADY OWNED,
; CLEANUP PREVIOUSLY FAILED, OR VMM IS UNAVAILABLE -- NEVER ALLOCATES A
; SECOND PAGE ON TOP OF ONE STILL OUTSTANDING.
; CLOBBERS: A, X, Y.
DVMMRUNTEST:
    LDA VMMOWNED
    BEQ @CHECKSTATE
    JMP @REJECT
@CHECKSTATE:
    LDA VMMPAGESTATE
    CMP #VMMSTATE_CLEANUPFAIL
    BNE @CHECKUNAVAIL
    JMP @REJECT
@CHECKUNAVAIL:
    CMP #VMMSTATE_UNAVAIL
    BNE @PROCEED           ; NOT CLEANUP-FAILED, NOT UNAVAILABLE
    JMP @REJECT        ; UNAVAILABLE: NO-OP, NEVER ALLOCATE
@PROCEED:
    LDA #VMMSTATE_RUNNING
    STA VMMPAGESTATE             ; RUNNING

    ; STEP: ALLOCATE ONE 4KB PAGE (256 PARAGRAPHS OF 16 BYTES EACH).
    LDX #<VMM_ALLOC_PARAGRAPHS
    LDY #>VMM_ALLOC_PARAGRAPHS
    LDA #DOS_ALLOC_MEM
    JSR OS_API
    BCC @ALLOCOK

    LDA #VMMSTATE_FAILED
    STA VMMPAGESTATE              ; FAILED
    LDA #VMMFAIL_ALLOC
    STA VMMFAILSTAGE               ; ALLOC
    RTS                             ; NO OWNERSHIP TAKEN, NO FREE ATTEMPTED

@ALLOCOK:
    STX VMMSEGHI
    STY VMMBANKID
    LDA #1
    STA VMMOWNED

    LDA #0
    STA VMMPATTERNIDX
@PATTERNLOOP:
    LDA #0
    STA VMMBLOCKIDX
@BLOCKLOOP:
    JSR DVMMFILLPATTERN            ; FILLS VMMBUFFER FOR THE CURRENT PATTERN

    JSR DVMMCHECKBLOCK              ; BOUNDS PROOF: VMMBLOCKIDX < 16
    BCC @WOK
    LDA #VMMFAIL_INTERNAL
    STA VMMFAILSTAGE                 ; INTERNAL
    LDA #VMMSTATE_FAILED
    STA VMMPAGESTATE
    JMP @CLEANUP
@WOK:
    JSR DVMMSETIDENTITY
    LDX #<VMMBUFFER
    LDY #>VMMBUFFER
    LDA #DOS_VMM_WRITE
    JSR OS_API
    BCC @READPHASE
    LDA #VMMFAIL_WRITE
    STA VMMFAILSTAGE                  ; WRITE
    LDA #VMMSTATE_FAILED
    STA VMMPAGESTATE
    JMP @CLEANUP

@READPHASE:
    JSR DVMMCLEARBUFFER
    JSR DVMMSETIDENTITY
    LDX #<VMMBUFFER
    LDY #>VMMBUFFER
    LDA #DOS_VMM_READ
    JSR OS_API
    BCC @COMPAREPHASE
    LDA #VMMFAIL_READ
    STA VMMFAILSTAGE                   ; READ
    LDA #VMMSTATE_FAILED
    STA VMMPAGESTATE
    JMP @CLEANUP

@COMPAREPHASE:
    JSR DVMMCOMPAREBLOCK                ; C SET ON MISMATCH; SAVES DETAILS
    BCC @BLOCKDONE
    LDA #VMMFAIL_COMPARE
    STA VMMFAILSTAGE                     ; COMPARE
    LDA #VMMSTATE_FAILED
    STA VMMPAGESTATE
    JMP @CLEANUP

@BLOCKDONE:
    INC VMMBLOCKIDX
    LDA VMMBLOCKIDX
    CMP #VMM_BLOCK_COUNT
    BCC @BLOCKLOOP

    INC VMMPATTERNIDX
    LDA VMMPATTERNIDX
    CMP #VMM_PATTERN_COUNT
    BCC @PATTERNLOOP

    ; ALL 3 PATTERNS PASSED: VMMPATTERNIDX IS NOW 3 (ONE PAST THE LAST VALID
    ; INDEX), WHICH WOULD RENDER AS "4 / 3". RESTORE IT TO 2 (THE LAST
    ; COMPLETED PATTERN) SO THE PASSED-STATE DISPLAY READS "3 / 3".
    DEC VMMPATTERNIDX

    ; ALL 3 PATTERNS PASSED ON ALL 16 BLOCKS. TENTATIVELY MARK THE STAGE AS
    ; FREE: THE ONLY REMAINING STEP THAT COULD STILL FAIL BEFORE PASSED IS
    ; DECLARED. IRRELEVANT IF THE FREE BELOW SUCCEEDS (STATE BECOMES PASSED,
    ; WHICH NEVER DISPLAYS A STAGE).
    LDA #VMMFAIL_FREE
    STA VMMFAILSTAGE

@CLEANUP:
    LDX VMMSEGHI
    LDY VMMBANKID
    LDA #DOS_FREE_MEM
    JSR OS_API
    BCS @FREEFAIL

    LDA #0
    STA VMMOWNED

    ; ONLY PROMOTE TO PASSED IF THIS IS THE ALL-CLEAR FALL-THROUGH (STATE
    ; STILL RUNNING). A REAL FAILURE ALREADY SET STATE TO FAILED ABOVE, AND
    ; MUST NOT BE OVERWRITTEN HERE.
    LDA VMMPAGESTATE
    CMP #VMMSTATE_RUNNING
    BNE @DONE
    LDA #VMMSTATE_PASSED
    STA VMMPAGESTATE                      ; PASSED
@DONE:
    RTS

@FREEFAIL:
    ; CLEANUP FAILED SUPERSEDES ONLY THE DISPLAYED STATUS; VMMFAILSTAGE KEEPS
    ; WHATEVER PRIMARY FAILURE (IF ANY) WAS ALREADY RECORDED. OWNERSHIP STAYS
    ; SET SO NO FURTHER ALLOCATION IS EVER ATTEMPTED.
    LDA #VMMSTATE_CLEANUPFAIL
    STA VMMPAGESTATE
    RTS

@REJECT:
    RTS

; DVMMSETIDENTITY - RESTORES THE VMM API PARAMETER BLOCK FOR THE CURRENT
; BLOCK INDEX BEFORE EVERY DOS_VMM_READ/DOS_VMM_WRITE CALL. NEVER TRUSTS ANY
; OF THESE ZERO-PAGE BYTES TO SURVIVE A PRIOR API CALL.
;
; INPUT: NONE (READS VMMSEGHI, VMMBANKID, VMMBLOCKIDX).
; OUTPUT: ZP $66/$67 = $0100 (BYTE COUNT), $68 = 0, $69 = VMMSEGHI,
;         $6A = 0, $6B = VMMBLOCKIDX, $6C = VMMBANKID.
; CLOBBERS: A.
DVMMSETIDENTITY:
    LDA #0
    STA $68                    ; VMMSEGLO -- VMMALLOC ALWAYS RETURNS 0 HERE
    LDA VMMSEGHI
    STA $69                    ; VMMSEGHI
    LDA #0
    STA $6A                    ; VMMOFFLO -- EVERY BLOCK IS 256-BYTE ALIGNED
    LDA VMMBLOCKIDX
    STA $6B                    ; VMMOFFHI -- BLOCK INDEX IS THE OFFSET HIGH
    LDA VMMBANKID
    STA $6C                    ; VMMBANK
    LDA #0
    STA $66                    ; HEXVALLO -- BYTE COUNT LOW
    LDA #1
    STA $67                    ; HEXVALHI -- BYTE COUNT HIGH ($0100 = 256)
    RTS

; DVMMCHECKBLOCK - BOUNDS PROOF: VMMBLOCKIDX MUST BE < 16 BEFORE ANY
; TRANSFER. UNREACHABLE IN CORRECT OPERATION (THE CALLER'S OWN BLOCK LOOP
; ALREADY BOUNDS VMMBLOCKIDX TO 0-15), KEPT AS THE PLAN'S REQUIRED DEFENSE-
; IN-DEPTH HELPER SO A FUTURE LOOP BUG CANNOT SILENTLY REQUEST OFFSET $1000
; OR BEYOND.
;
; OUTPUT: C CLEAR = IN BOUNDS. C SET = BOUNDS VIOLATION (INTERNAL FAILURE).
; CLOBBERS: A.
DVMMCHECKBLOCK:
    LDA VMMBLOCKIDX
    CMP #VMM_BLOCK_COUNT
    BCC @OK
    SEC
    RTS
@OK:
    CLC
    RTS

; DVMMFILLPATTERN - FILLS ALL 256 BYTES OF VMMBUFFER WITH THE CURRENT
; PATTERN'S EXPECTED VALUE AT EACH LOCAL INDEX (0-255), FOR THE UPCOMING
; WRITE.
; CLOBBERS: A, X.
DVMMFILLPATTERN:
    LDX #0
@LOOP:
    JSR DVMMGENBYTE
    STA VMMBUFFER,X
    INX
    BNE @LOOP              ; EXACTLY 256 ITERATIONS: X WRAPS 255->0
    RTS

; DVMMCLEARBUFFER - ZEROES ALL 256 BYTES OF VMMBUFFER BEFORE A READ, SO A
; NO-OP/FAILED READ CAN NEVER ACCIDENTALLY LEAVE THE PRIOR WRITE'S OWN
; PATTERN SITTING IN THE BUFFER AND FALSELY COMPARE EQUAL.
; CLOBBERS: A, X.
DVMMCLEARBUFFER:
    LDA #0
    LDX #0
@LOOP:
    STA VMMBUFFER,X
    INX
    BNE @LOOP
    RTS

; DVMMGENBYTE - REGENERATES THE EXPECTED BYTE FOR THE CURRENT PATTERN
; (VMMPATTERNIDX) AT LOCAL INDEX X (0-255). BECAUSE EVERY BLOCK IS 256-BYTE
; ALIGNED, THE ABSOLUTE OFFSET'S PARITY AND MOD-256 VALUE EXACTLY EQUAL THIS
; LOCAL INDEX'S -- NO SEPARATE ABSOLUTE-OFFSET ARITHMETIC IS NEEDED.
;
; PATTERN 0: $00 (INDEX EVEN) / $FF (INDEX ODD).
; PATTERN 1: $55 (INDEX EVEN) / $AA (INDEX ODD).
; PATTERN 2: INCREMENTING (VALUE == INDEX).
;
; INPUT: X = LOCAL INDEX (0-255). READS VMMPATTERNIDX.
; OUTPUT: A = GENERATED BYTE. CLOBBERS: A. PRESERVES X.
DVMMGENBYTE:
    LDA VMMPATTERNIDX
    CMP #2
    BEQ @INCR
    CMP #1
    BEQ @Z55AA

    TXA
    AND #1
    BEQ @Z00
    LDA #$FF
    RTS
@Z00:
    LDA #$00
    RTS
@Z55AA:
    TXA
    AND #1
    BEQ @Z55
    LDA #$AA
    RTS
@Z55:
    LDA #$55
    RTS
@INCR:
    TXA
    RTS

; DVMMCOMPAREBLOCK - COMPARES ALL 256 BYTES OF VMMBUFFER (JUST READ BACK)
; AGAINST THE REGENERATED EXPECTED PATTERN. STOPS AT THE FIRST MISMATCH.
;
; OUTPUT: C CLEAR = ALL 256 BYTES MATCHED. C SET = MISMATCH FOUND;
;         VMMFAILOFFHI = VMMBLOCKIDX, VMMFAILOFFLO = LOCAL INDEX,
;         VMMFAILEXPECT/VMMFAILACTUAL = THE MISMATCHED BYTES.
; CLOBBERS: A, X.
DVMMCOMPAREBLOCK:
    LDX #0
@LOOP:
    JSR DVMMGENBYTE               ; A = EXPECTED BYTE FOR LOCAL INDEX X
    CMP VMMBUFFER,X
    BNE @MISMATCH
    INX
    BNE @LOOP
    CLC
    RTS
@MISMATCH:
    STA VMMFAILEXPECT              ; A STILL HOLDS THE EXPECTED BYTE (CMP
                                     ; DOES NOT MODIFY A)
    LDA VMMBUFFER,X
    STA VMMFAILACTUAL
    LDA VMMBLOCKIDX
    STA VMMFAILOFFHI
    STX VMMFAILOFFLO
    SEC
    RTS
